     5	public class ReservationService {
     6	    private final ReservationRepository reservations;
     7	    private final Notifier notifier;
     8	
     9	    public ReservationService(ReservationRepository reservations, Notifier notifier) {
    10	        this.reservations = reservations;
    11	        this.notifier = notifier;
    12	    }
    13	
    14	    public synchronized Reservation create(BookingRequest request) {
    15	        Room room = RoomCatalog.find(request.roomNumber())
    16	                .orElseThrow(() -> new PousadaException(ErrorCode.ROOM_NOT_FOUND,
    17	                        "Quarto " + request.roomNumber() + " não existe"));
    18	        if (request.guests() > room.capacity()) {
    19	            throw new PousadaException(ErrorCode.CAPACITY_EXCEEDED,
    20	                    "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    21	        }
    22	        boolean taken = reservations.findAll().stream()
    23	                .filter(r -> r.room().number() == room.number())
    24	                .filter(r -> r.status() != ReservationStatus.CANCELLED)
    25	                .anyMatch(r -> r.overlaps(request.checkIn(), request.checkOut()));
    26	        if (taken) {
    27	            throw new PousadaException(ErrorCode.ROOM_UNAVAILABLE,
    28	                    "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    29	        }
    30	        return reservations.insert(Reservation.pending(room, request.guestName(), request.guestEmail(),
    31	                request.identity(), request.checkIn(), request.checkOut(), request.guests(), request.ratePlan()));
    32	    }
    33	
    34	    public Reservation get(int id) {
    35	        return reservations.find(id).orElseThrow(() -> new PousadaException(ErrorCode.RESERVATION_NOT_FOUND,
    36	                "Reserva " + id + " não existe"));
    37	    }
    38	
    39	    public synchronized Reservation confirm(int id) {
    40	        Reservation reservation = get(id);
    41	        reservation.confirm();
    42	        reservations.update(reservation);
    43	        notifier.reservationConfirmed(reservation);
    44	        return reservation;
    45	    }
    46	
    47	    public synchronized Reservation cancel(int id) {
    48	        Reservation reservation = get(id);
    49	        reservation.cancel();
    50	        reservations.update(reservation);
    51	        return reservation;
    52	    }
    53	
    54	    public synchronized Reservation checkIn(int id) {
    55	        Reservation reservation = get(id);
    56	        reservation.startStay();
    57	        reservations.update(reservation);
    58	        return reservation;
    59	    }
    60	
    61	    public synchronized Document checkOut(int id) {
    62	        Reservation reservation = get(id);
    63	        reservation.endStay();
    64	        reservations.update(reservation);
    65	        return reservation.identity().document(reservation);
