    20	    public Connection connect() throws SQLException {
    21	        return DriverManager.getConnection(url, user, password);
    22	    }
    23	
    24	    /** Cria as tabelas; tenta de novo por um tempo caso o banco ainda esteja subindo. */
    25	    public void createSchema() {
    26	        SQLException last = null;
    27	        for (int attempt = 0; attempt < 30; attempt++) {
    28	            try (Connection c = connect(); Statement s = c.createStatement()) {
    29	                s.execute("""
    30	                        CREATE TABLE IF NOT EXISTS reservations (
    31	                            id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    32	                            room_number INTEGER NOT NULL,
    33	                            guest_name TEXT NOT NULL,
    34	                            guest_email TEXT NOT NULL,
    35	                            identity_kind TEXT NOT NULL,
    36	                            identity_data TEXT NOT NULL,
    37	                            check_in DATE NOT NULL,
    38	                            check_out DATE NOT NULL,
    39	                            guests INTEGER NOT NULL,
    40	                            rate_plan TEXT NOT NULL,
    41	                            nights INTEGER NOT NULL,
    42	                            subtotal NUMERIC(12,2) NOT NULL,
    43	                            discount NUMERIC(12,2) NOT NULL,
    44	                            total NUMERIC(12,2) NOT NULL,
    45	                            status TEXT NOT NULL,
    46	                            amount_paid NUMERIC(12,2) NOT NULL,
    47	                            refund NUMERIC(12,2)
    48	                        )""");
    49	                s.execute("""
    50	                        CREATE TABLE IF NOT EXISTS messages (
    51	                            id INTEGER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    52	                            channel TEXT NOT NULL,
    53	                            recipient TEXT NOT NULL,
    54	                            subject TEXT NOT NULL,
    55	                            body TEXT NOT NULL
    56	                        )""");
    57	                return;
    58	            } catch (SQLException e) {
    59	                last = e;
    60	                try {
    61	                    Thread.sleep(1000);
    62	                } catch (InterruptedException ie) {
    63	                    Thread.currentThread().interrupt();
    64	                    break;
    65	                }
    66	            }
    67	        }
    68	        throw new IllegalStateException("Não foi possível preparar o banco de dados", last);
    69	    }
