    19	
    20	    @Override
    21	    public Reservation insert(Reservation r) {
    22	        String sql = "INSERT INTO reservations (room_number, guest_name, guest_email, identity_kind, identity_data,"
    23	                + " check_in, check_out, guests, rate_plan, nights, subtotal, discount, total, status,"
    24	                + " amount_paid, refund) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)";
    25	        try (Connection c = db.connect();
    26	             PreparedStatement ps = c.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS)) {
    27	            bind(ps, r, 1);
    28	            ps.executeUpdate();
    29	            try (ResultSet keys = ps.getGeneratedKeys()) {
    30	                keys.next();
    31	                return r.withId(keys.getInt(1));
    32	            }
    33	        } catch (SQLException e) {
    34	            throw new IllegalStateException(e);
    35	        }
    36	    }
    37	
    38	    @Override
    39	    public void update(Reservation r) {
    40	        try (Connection c = db.connect();
    41	             PreparedStatement ps = c.prepareStatement(
    42	                     "UPDATE reservations SET status = ?, amount_paid = ?, refund = ? WHERE id = ?")) {
    43	            ps.setString(1, r.status().name());
    44	            ps.setBigDecimal(2, r.amountPaid());
    45	            ps.setBigDecimal(3, r.refund());
    46	            ps.setInt(4, r.id());
    47	            ps.executeUpdate();
    48	        } catch (SQLException e) {
    49	            throw new IllegalStateException(e);
    50	        }
    51	    }
    52	
    53	    @Override
    54	    public Optional<Reservation> find(int id) {
    55	        try (Connection c = db.connect();
    56	             PreparedStatement ps = c.prepareStatement("SELECT * FROM reservations WHERE id = ?")) {
    57	            ps.setInt(1, id);
    58	            try (ResultSet rs = ps.executeQuery()) {
    59	                return rs.next() ? Optional.of(read(rs)) : Optional.empty();
    60	            }
    61	        } catch (SQLException e) {
    62	            throw new IllegalStateException(e);
    63	        }
    64	    }
    65	
    66	    @Override
    67	    public List<Reservation> findAll() {
    68	        try (Connection c = db.connect();
    69	             PreparedStatement ps = c.prepareStatement("SELECT * FROM reservations ORDER BY id");
    70	             ResultSet rs = ps.executeQuery()) {
    71	            List<Reservation> all = new ArrayList<>();
    72	            while (rs.next()) {
    73	                all.add(read(rs));
    74	            }
    75	            return all;
    76	        } catch (SQLException e) {
    77	            throw new IllegalStateException(e);
    78	        }
    79	    }
    80	
    81	    private static void bind(PreparedStatement ps, Reservation r, int i) throws SQLException {
    82	        ps.setInt(i++, r.room().number());
    83	        ps.setString(i++, r.guestName());
    84	        ps.setString(i++, r.guestEmail());
    85	        ps.setString(i++, IdentityKinds.kindName(r.identity()));
    86	        ps.setString(i++, IdentityKinds.serialize(r.identity()));
    87	        ps.setDate(i++, Date.valueOf(r.checkIn()));
    88	        ps.setDate(i++, Date.valueOf(r.checkOut()));
    89	        ps.setInt(i++, r.guests());
