    92	        ps.setBigDecimal(i++, r.quote().subtotal());
    93	        ps.setBigDecimal(i++, r.quote().discount());
    94	        ps.setBigDecimal(i++, r.quote().total());
    95	        ps.setString(i++, r.status().name());
    96	        ps.setBigDecimal(i++, r.amountPaid());
    97	        ps.setBigDecimal(i, r.refund());
    98	    }
    99	
   100	    private static Reservation read(ResultSet rs) throws SQLException {
   101	        Quote quote = new Quote(rs.getInt("nights"), rs.getBigDecimal("subtotal"),
   102	                rs.getBigDecimal("discount"), rs.getBigDecimal("total"));
   103	        return new Reservation(rs.getInt("id"), RoomCatalog.find(rs.getInt("room_number")).orElseThrow(),
   104	                rs.getString("guest_name"), rs.getString("guest_email"),
   105	                IdentityKinds.restore(rs.getString("identity_kind"), rs.getString("identity_data")),
   106	                rs.getDate("check_in").toLocalDate(), rs.getDate("check_out").toLocalDate(),
   107	                rs.getInt("guests"), RatePlan.valueOf(rs.getString("rate_plan")), quote,
   108	                ReservationStatus.valueOf(rs.getString("status")), rs.getBigDecimal("amount_paid"),
   109	                rs.getBigDecimal("refund"));
   110	    }
