     9	
    10	/** Único lugar que conhece todos os jeitos de se identificar. Um novo tipo entra só aqui. */
    11	public final class IdentityKinds {
    12	    private static final List<IdentityKind> ALL = List.of(
    13	            CpfIdentity.KIND,
    14	            CompanyIdentity.KIND,
    15	            PassportIdentity.KIND);
    16	
    17	    private static final ObjectMapper JSON = new ObjectMapper();
    18	
    19	    private IdentityKinds() {
    20	    }
    21	
    22	    /** Todos os campos de identificação que a API expõe, na ordem de cadastro. */
    23	    public static List<String> allFieldNames() {
    24	        List<String> names = new ArrayList<>();
    25	        ALL.forEach(k -> names.addAll(k.fieldNames()));
    26	        return names;
    27	    }
    28	
    29	    /** Lê a identificação do corpo: exatamente um tipo, com todos os seus campos preenchidos. */
    30	    public static GuestIdentity fromBody(Map<String, Object> body) {
    31	        List<IdentityKind> present = ALL.stream()
    32	                .filter(k -> k.fieldNames().stream().anyMatch(f -> body.get(f) != null))
    33	                .toList();
    34	        if (present.size() != 1) {
    35	            throw invalid();
    36	        }
    37	        IdentityKind kind = present.get(0);
    38	        Map<String, String> values = new LinkedHashMap<>();
    39	        for (String field : kind.fieldNames()) {
    40	            if (!(body.get(field) instanceof String s) || s.isBlank()) {
    41	                throw invalid();
    42	            }
    43	            values.put(field, s.trim());
    44	        }
    45	        return kind.create(values);
    46	    }
    47	
    48	    public static String kindName(GuestIdentity identity) {
    49	        return identity.kind().name();
    50	    }
    51	
    52	    public static String serialize(GuestIdentity identity) {
    53	        try {
    54	            return JSON.writeValueAsString(identity.values());
    55	        } catch (Exception e) {
    56	            throw new IllegalStateException(e);
    57	        }
    58	    }
    59	
    60	    @SuppressWarnings("unchecked")
    61	    public static GuestIdentity restore(String kindName, String data) {
    62	        try {
    63	            Map<String, String> values = JSON.readValue(data, Map.class);
    64	            return ALL.stream().filter(k -> k.name().equals(kindName)).findFirst()
    65	                    .orElseThrow(() -> new IllegalStateException("Tipo de identificação desconhecido: " + kindName))
    66	                    .create(values);
    67	        } catch (IllegalStateException e) {
    68	            throw e;
    69	        } catch (Exception e) {
    70	            throw new IllegalStateException(e);
    71	        }
    72	    }
