     1	package br.com.mare.pousada;
     2	
     3	import java.math.BigDecimal;
     4	import java.time.LocalDate;
     5	import java.time.Month;
     6	
     7	public final class PricingPolicy {
     8	    private static final BigDecimal HIGH_SEASON_MARKUP = new BigDecimal("1.20");
     9	
    10	    private PricingPolicy() {
    11	    }
    12	
    13	    public static boolean isHighSeason(LocalDate night) {
    14	        Month month = night.getMonth();
    15	        return month == Month.JANUARY || month == Month.FEBRUARY || month == Month.JULY
    16	                || (month == Month.DECEMBER && night.getDayOfMonth() >= 15);
    17	    }
    18	
    19	    public static BigDecimal nightPrice(Room room, LocalDate night) {
    20	        BigDecimal rate = room.type().nightlyRate();
    21	        return isHighSeason(night) ? Money.percent(rate, HIGH_SEASON_MARKUP) : Money.round(rate);
    22	    }
    23	
    24	    public static Quote quote(Room room, RatePlan plan, LocalDate checkIn, LocalDate checkOut) {
    25	        BigDecimal subtotal = Money.ZERO;
    26	        int nights = 0;
    27	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
    28	            subtotal = Money.round(subtotal.add(nightPrice(room, night)));
    29	            nights++;
    30	        }
    31	        BigDecimal discount = plan.discountOn(subtotal);
    32	        return new Quote(nights, subtotal, discount, Money.round(subtotal.subtract(discount)));
    33	    }
    34	}
